function drag(id, colKey){const card=document.querySelector(`.kcard[data-id="${id}"]`);const col=document.querySelector(`.col[data-col="${colKey}"]`);const r=card.getBoundingClientRect(),c=col.getBoundingClientRect();const sx=r.left+5,sy=r.top+5,tx=c.left+c.width/2,ty=c.bottom-10;card.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,clientX:sx,clientY:sy}));document.dispatchEvent(new PointerEvent('pointermove',{bubbles:true,clientX:tx,clientY:ty}));document.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,clientX:tx,clientY:ty}));}
drag('c1','done');drag('c2','doing');
const b={};document.querySelectorAll('.kcard').forEach(k=>b[k.textContent]=k.closest('.col').dataset.col);return b;
